1: // play-button (data-run-command) click handler
2: document.addEventListener("click", (ev) => {
3:   const code = ev.target.closest("[data-run-command]");
4:   if (!code) return;
5:   const command = commandFromFence(code.textContent);
6:   // Prefix a cd into the workspace so the command always runs in the
7:   // correct directory. JSON.stringify quotes the path "safely".
8:   const wsPath = (window.Panels && typeof window.Panels.workspace === "function") ? window.Panels.workspace() : "";
9:   const full = wsPath ? 'cd ' + JSON.stringify(wsPath) + ' && ' + command : command;
10:   Panels.setOpen(true);
11:   // The terminal panel writes the string verbatim to its persistent POSIX sh.
12:   Panels.select("terminal", { command: full });
13: });
